import React, { useState, useEffect } from 'react';

function App() {
  const [contacts, setContacts] = useState([]);
  const [formData, setFormData] = useState({
    name: '',
    phone: '',
    email: ''
  });

  // Handle input changes
  const handleInputChange = (e) => {
    const { name, value } = e.target;
    setFormData(prevState => ({
      ...prevState,
      [name]: value
    }));
  };

  // Handle form submission
  const handleSubmit = (e) => {
    e.preventDefault();

    // Add new contact to the contacts array
    const newContact = {
      id: Date.now(), // Temporary ID
      ...formData
    };

    setContacts(prevContacts => [...prevContacts, newContact]);

    // Clear the form
    setFormData({
      name: '',
      phone: '',
      email: ''
    });
  };

  // Handle contact deletion
  const handleDelete = (id) => {
    setContacts(prevContacts => prevContacts.filter(contact => contact.id !== id));
  };

  return (
    <div className="container" style={{ padding: '20px' }}>
      <h1>Contact Management System</h1>

      <div className="form-section" style={{ marginBottom: '20px' }}>
        <h2>Create Contact</h2>
        <form onSubmit={handleSubmit}>
          <div style={{ marginBottom: '10px' }}>
            <input
              type="text"
              name="name"
              value={formData.name}
              onChange={handleInputChange}
              placeholder="Name"
              required
              style={{ marginRight: '10px', padding: '5px' }}
            />
            <input
              type="tel"
              name="phone"
              value={formData.phone}
              onChange={handleInputChange}
              placeholder="Phone"
              required
              style={{ marginRight: '10px', padding: '5px' }}
            />
            <input
              type="email"
              name="email"
              value={formData.email}
              onChange={handleInputChange}
              placeholder="Email"
              required
              style={{ marginRight: '10px', padding: '5px' }}
            />
            <button type="submit" style={{ padding: '5px 10px' }}>Add Contact</button>
          </div>
        </form>
      </div>

      <div className="contacts-list">
        <h2>Contacts List</h2>
        {contacts.length === 0 ? (
          <p>No contacts yet</p>
        ) : (
          <ul style={{ listStyle: 'none', padding: 0 }}>
            {contacts.map(contact => (
              <li key={contact.id} style={{ marginBottom: '10px', padding: '10px', border: '1px solid #ddd' }}>
                {contact.name} - {contact.phone} - {contact.email}
                <button 
                  onClick={() => handleDelete(contact.id)}
                  style={{ marginLeft: '10px', padding: '5px', backgroundColor: '#ff4444', color: 'white', border: 'none' }}
                >
                  Delete
                </button>
              </li>
            ))}
          </ul>
        )}
      </div>
    </div>
  );
}

export default App;
